def ladder_length(begin, end, word_list):
    words = list(dict.fromkeys([begin] + word_list))
    if end not in words:
        return 0
    adj = defaultdict(list)
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if sum(a != b for a, b in zip(words[i], words[j])) == 1:
                adj[words[i]].append(words[j]); adj[words[j]].append(words[i])
    seen, queue = {begin}, deque([(begin, 1)])
    while queue:
        w, d = queue.popleft()
        if w == end:
            return d
        for nb in adj[w]:
            if nb not in seen:
                seen.add(nb); queue.append((nb, d + 1))
    return 0

def ladder_length(begin, end, word_list):
    words = set(word_list)
    if end not in words:
        return 0
    queue = deque([(begin, 1)])
    words.discard(begin)
    while queue:
        w, d = queue.popleft()
        if w == end:
            return d
        for i in range(len(w)):
            for ch in "abcdefghijklmnopqrstuvwxyz":
                nxt = w[:i] + ch + w[i + 1:]
                if nxt in words:
                    words.remove(nxt)            # visited
                    queue.append((nxt, d + 1))
    return 0

def ladder_length(begin, end, word_list):
    words = set(word_list)
    if end not in words:
        return 0
    L = len(begin)
    buckets = defaultdict(list)
    for w in words | {begin}:
        for i in range(L):
            buckets[w[:i] + "*" + w[i + 1:]].append(w)
    front, back, seen, steps = {begin}, {end}, {begin, end}, 1
    while front and back:
        if len(front) > len(back):
            front, back = back, front
        steps += 1
        nxt = set()
        for w in front:
            for i in range(L):
                for nb in buckets[w[:i] + "*" + w[i + 1:]]:
                    if nb in back:
                        return steps
                    if nb not in seen:
                        seen.add(nb)
                        nxt.add(nb)
        front = nxt
    return 0
